"""The single source of truth for iArch user state.

Rules implemented here, and documented in docs/ARCHITECTURE.md:

* user settings live in ``~/.config/iarch/`` (``settings.json``,
  ``keybinds.json``, ``contacts.json``, ``presets/``);
* the repository ships defaults in ``data/`` and a user never edits repo files;
  loading a name merges ``data/<name>.default.json`` under the user's file;
* generated files start with :data:`GENERATED_HEADER` and are always written
  atomically: temp file in the destination directory, validate, ``os.replace``;
* every generator keeps the last five backups of what it overwrote in
  ``~/.local/state/iarch/backups/``.

Both directories honour environment overrides so tests never touch a real
home: ``IARCH_CONFIG_DIR`` and ``IARCH_STATE_DIR``.
"""
from __future__ import annotations

import json
import os
import stat
import tempfile
import time
from pathlib import Path
from typing import Any, Dict, Mapping, Optional

GENERATED_HEADER = "-- GENERATED BY iArch. DO NOT EDIT. Change settings in iArch Settings."
BACKUP_LIMIT = 5

# The sentence above, without its Lua comment marker, plus the marker each
# generated file type uses. JSON cannot carry comments at all, so generated JSON
# keeps the sentence as its first key ("_generated"); see header_for().
_HEADER_SENTENCE = GENERATED_HEADER[len("-- "):]
_COMMENT_PREFIX = {".lua": "-- ", ".sh": "# ", ".fish": "# ", ".toml": "# ", ".conf": "# ", ".kvconfig": "; "}


class ConfigError(RuntimeError):
    """Raised when user state or a generated target is not safe to touch."""


def config_dir(env: Optional[Mapping[str, str]] = None) -> Path:
    env = os.environ if env is None else env
    value = env.get("IARCH_CONFIG_DIR")
    root = Path(value) if value else Path.home() / ".config" / "iarch"
    if not root.is_absolute():
        raise ConfigError(f"IARCH_CONFIG_DIR must be absolute: {value!r}")
    return root


def state_dir(env: Optional[Mapping[str, str]] = None) -> Path:
    env = os.environ if env is None else env
    value = env.get("IARCH_STATE_DIR")
    root = Path(value) if value else Path.home() / ".local" / "state" / "iarch"
    if not root.is_absolute():
        raise ConfigError(f"IARCH_STATE_DIR must be absolute: {value!r}")
    return root


def backup_dir(env: Optional[Mapping[str, str]] = None) -> Path:
    return state_dir(env) / "backups"


def defaults_path(name: str, repo_root: Path) -> Path:
    return repo_root / "data" / f"{name}.default.json"


def user_path(name: str, env: Optional[Mapping[str, str]] = None) -> Path:
    return config_dir(env) / f"{name}.json"


def _merge(base: Any, overlay: Any) -> Any:
    """Deep-merge ``overlay`` onto ``base``; the user's values win."""
    if isinstance(base, dict) and isinstance(overlay, dict):
        merged = dict(base)
        for key, value in overlay.items():
            merged[key] = _merge(base[key], value) if key in base else value
        return merged
    return overlay


def load(name: str, repo_root: Path, env: Optional[Mapping[str, str]] = None) -> Dict[str, Any]:
    """Return repository defaults for ``name`` with the user's file merged on top."""
    defaults_file = defaults_path(name, repo_root)
    if not defaults_file.is_file():
        raise ConfigError(f"Repository defaults are missing: {defaults_file}")
    merged = json.loads(defaults_file.read_text(encoding="utf-8"))
    own = user_path(name, env)
    if own.is_file():
        merged = _merge(merged, json.loads(own.read_text(encoding="utf-8")))
    return merged


def stamp(text: str) -> str:
    return text if text.startswith(GENERATED_HEADER) else f"{GENERATED_HEADER}\n{text}"


def header_for(path: Path) -> str:
    """The header line as it must appear at the top of ``path`` for its file type."""
    if path.suffix == ".json":
        return GENERATED_HEADER  # stored as the value of the "_generated" key
    if path.suffix == ".css":
        # CSS has no line comment at all, so the sentence is wrapped in a block
        # comment. Emitting it with the "#" default would put a parse error on
        # line 1 of every stylesheet this project writes.
        return f"/* {_HEADER_SENTENCE} */"
    if path.name == "fonts.conf":
        # A fontconfig file is XML, where "#" is not a comment. It carries no XML
        # declaration (a leading comment would stop it being one), so the sentence
        # goes first as an XML comment and the <fontconfig> root follows it. Keyed
        # on the standard fontconfig filename, not the directory, so an --output-dir
        # render gets the same header as the shipped one.
        return f"<!-- {_HEADER_SENTENCE} -->"
    return _COMMENT_PREFIX.get(path.suffix, "# ") + _HEADER_SENTENCE


def is_header_line(line: str) -> bool:
    """True when ``line`` is the GENERATED sentence in any form this emits."""
    stripped = line.strip()
    if stripped.startswith(GENERATED_HEADER) or stripped == _HEADER_SENTENCE:
        return True
    if stripped.startswith("<!--") and stripped.endswith("-->"):
        # The XML comment form a fontconfig file uses.
        if stripped[4:-3].strip() == _HEADER_SENTENCE:
            return True
    for prefix in ("-- ", "# ", "/* ", "; ", "// "):
        if not stripped.startswith(prefix):
            continue
        body = stripped[len(prefix):].strip()
        if body.endswith("*/"):
            body = body[:-2].strip()
        if body == _HEADER_SENTENCE:
            return True
    return False


def default_mode() -> int:
    """The mode a newly created configuration file should have: 0666 less umask."""
    umask = os.umask(0o022)
    os.umask(umask)
    return 0o666 & ~umask


def atomic_write(path: Path, text: str, validate_json: Optional[bool] = None) -> None:
    """Write ``text`` to ``path`` without ever leaving a half-written file.

    The temp file is created in the destination directory so the rename is
    atomic on the same filesystem; JSON payloads are parsed before the rename.

    Permissions are carried over from the file being replaced, and a new file
    gets the usual 0666-less-umask. ``NamedTemporaryFile`` creates 0600, so
    without this every regeneration would quietly tighten a configuration file
    that the rest of ``~/.config`` expects to be readable -- and a generated file
    is rewritten often.
    """
    path = Path(path)
    if path.is_symlink():
        raise ConfigError(f"Refusing to write through a symlink: {path}")
    if validate_json is None:
        validate_json = path.suffix == ".json"
    if validate_json:
        json.loads(text)
    mode = stat.S_IMODE(path.stat().st_mode) if path.exists() else default_mode()
    path.parent.mkdir(parents=True, exist_ok=True)
    handle = tempfile.NamedTemporaryFile(
        "w", encoding="utf-8", dir=str(path.parent), prefix=f".{path.name}.", suffix=".tmp", delete=False
    )
    tmp = Path(handle.name)
    try:
        with handle:
            handle.write(text)
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(tmp, mode)
        os.replace(tmp, path)
    except BaseException:
        tmp.unlink(missing_ok=True)
        raise


def rotate_backups(directory: Path, limit: int = BACKUP_LIMIT) -> None:
    """Keep only the ``limit`` most recent backups in ``directory``."""
    if not directory.is_dir():
        return
    # Backup names start with a sortable timestamp, so name order is age order
    # even when several are written inside the same clock second.
    backups = sorted((p for p in directory.iterdir() if p.name.endswith(".bak")), key=lambda p: p.name)
    for stale in backups[:-limit] if len(backups) > limit else []:
        stale.unlink()


def backup_of(path: Path, env: Optional[Mapping[str, str]] = None) -> Optional[Path]:
    """Copy ``path`` aside before it is overwritten; returns the backup path."""
    path = Path(path)
    if not path.is_file():
        return None
    directory = backup_dir(env)
    directory.mkdir(parents=True, exist_ok=True)
    stamp_name = str(path).strip("/").replace("/", "_")
    now = time.time()
    stamp = time.strftime("%Y%m%d-%H%M%S", time.localtime(now))
    nanos = int((now % 1) * 1_000_000_000)
    target = directory / f"{stamp_name}.{stamp}-{nanos:09d}-{os.getpid()}.bak"
    while target.exists():  # two writes inside one nanosecond cannot share a name
        nanos += 1
        target = directory / f"{stamp_name}.{stamp}-{nanos:09d}-{os.getpid()}.bak"
    target.write_bytes(path.read_bytes())
    rotate_backups(directory)
    return target


def save(name: str, payload: Mapping[str, Any], env: Optional[Mapping[str, str]] = None) -> Path:
    """Persist the user's settings for ``name``, backing the previous file up."""
    target = user_path(name, env)
    if target.is_file():
        backup_of(target, env)
    atomic_write(target, json.dumps(dict(payload), indent=2, ensure_ascii=False) + "\n")
    return target


def write_generated(path: Path, body: str, env: Optional[Mapping[str, str]] = None) -> Path:
    """Write a generated file: header first, backup kept, atomic rename last."""
    path = Path(path)
    if path.is_file():
        backup_of(path, env)
    if path.suffix == ".json":
        data = json.loads(body)
        if "_generated" in data:
            raise ConfigError("generated JSON must not carry a caller-supplied _generated key")
        text = json.dumps({"_generated": GENERATED_HEADER, **data}, indent=2, ensure_ascii=False) + "\n"
    else:
        text = f"{header_for(path)}\n{body if body.endswith(chr(10)) or not body else body}\n"
    atomic_write(path, text)
    return path
